CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL);
CREATE TABLE "clinics_clinic" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "subdomain" varchar(63) NOT NULL UNIQUE, "discipline" varchar(20) NOT NULL, "address" text NOT NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "logo_url" varchar(200) NOT NULL, "paper_size" varchar(5) NOT NULL, "primary_color" varchar(7) NOT NULL, "tagline" varchar(255) NOT NULL, "registration_number" varchar(50) NOT NULL, "letterhead_mode" varchar(10) NOT NULL, "top_margin_mm" integer unsigned NOT NULL CHECK ("top_margin_mm" >= 0), "bottom_margin_mm" integer unsigned NOT NULL CHECK ("bottom_margin_mm" >= 0), "google_review_url" varchar(200) NOT NULL, "plan" varchar(10) NOT NULL, "active_patient_limit" integer unsigned NOT NULL CHECK ("active_patient_limit" >= 0), "is_active" bool NOT NULL, "is_demo" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "clinics_clinicinvitation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL, "role" varchar(20) NOT NULL, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "token" char(32) NOT NULL UNIQUE, "invited_by_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL, "expires_at" datetime NOT NULL, "accepted_at" datetime NULL);
CREATE TABLE "clinics_dataexportaudit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "actor_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "endpoint" varchar(100) NOT NULL, "row_count" integer unsigned NOT NULL CHECK ("row_count" >= 0), "created_at" datetime NOT NULL);
CREATE TABLE "consultations_consultation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "conducted_by_id" bigint NULL REFERENCES "users_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "weight" decimal NULL, "height" decimal NULL, "pulse_rate" smallint unsigned NULL CHECK ("pulse_rate" >= 0), "temperature" decimal NULL, "bp_systolic" smallint unsigned NULL CHECK ("bp_systolic" >= 0), "bp_diastolic" smallint unsigned NULL CHECK ("bp_diastolic" >= 0), "appetite" varchar(10) NOT NULL, "appetite_notes" text NOT NULL, "bowel" varchar(10) NOT NULL, "bowel_notes" text NOT NULL, "micturition" varchar(10) NOT NULL, "micturition_notes" text NOT NULL, "sleep_quality" varchar(10) NOT NULL, "sleep_notes" text NOT NULL, "mental_state" text NOT NULL, "diagnostic_data" text NOT NULL CHECK ((JSON_VALID("diagnostic_data") OR "diagnostic_data" IS NULL)), "chief_complaints" text NOT NULL, "history_of_present_illness" text NOT NULL, "diagnosis" text NOT NULL, "consultation_date" date NOT NULL, "is_imported" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "unique_consultation_per_patient_day" UNIQUE ("clinic_id", "patient_id", "consultation_date"));
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action_time" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "feedback_feedback" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "users_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "category" varchar(10) NOT NULL, "title" varchar(256) NOT NULL, "description" text NOT NULL, "screenshot_url" varchar(200) NOT NULL, "page_url" varchar(200) NOT NULL, "user_role" varchar(20) NOT NULL, "browser_info" varchar(256) NOT NULL, "github_issue_url" varchar(200) NOT NULL, "github_issue_number" integer unsigned NULL CHECK ("github_issue_number" >= 0), "status" varchar(10) NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "integrations_ruthvajourneyref" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "consultation_id" bigint NULL REFERENCES "consultations_consultation" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "ruthva_journey_id" varchar(100) NOT NULL UNIQUE, "ruthva_patient_id" varchar(100) NOT NULL, "status" varchar(20) NOT NULL, "risk_level" varchar(20) NOT NULL, "risk_reason" varchar(255) NOT NULL, "start_date" date NULL, "next_visit_date" date NULL, "last_visit_date" date NULL, "missed_visits" smallint unsigned NOT NULL CHECK ("missed_visits" >= 0), "duration_days" smallint unsigned NOT NULL CHECK ("duration_days" >= 0), "followup_interval_days" smallint unsigned NOT NULL CHECK ("followup_interval_days" >= 0), "consent_given_at" datetime NULL, "last_synced_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "patients_familyhistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "relation" varchar(100) NOT NULL, "disease" varchar(255) NOT NULL, "duration" varchar(100) NOT NULL, "remarks" text NOT NULL);
CREATE TABLE "patients_medicalhistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "disease" varchar(255) NOT NULL, "duration" varchar(100) NOT NULL, "medication" text NOT NULL);
CREATE TABLE "patients_patient" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "record_id" varchar(20) NOT NULL, "name" varchar(255) NOT NULL, "age" smallint unsigned NOT NULL CHECK ("age" >= 0), "date_of_birth" date NULL, "gender" varchar(10) NOT NULL, "phone" varchar(15) NOT NULL, "whatsapp_number" varchar(15) NOT NULL, "email" varchar(254) NOT NULL, "address" text NOT NULL, "blood_group" varchar(5) NOT NULL, "occupation" varchar(100) NOT NULL, "marital_status" varchar(20) NOT NULL, "referred_by" varchar(255) NOT NULL, "allergies" text NOT NULL, "food_habits" varchar(20) NOT NULL, "activity_level" varchar(20) NOT NULL, "menstrual_history" text NOT NULL, "number_of_children" smallint unsigned NULL CHECK ("number_of_children" >= 0), "vaccination_records" text NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "unique_record_id_per_clinic" UNIQUE ("clinic_id", "record_id"));
CREATE TABLE "pharmacy_dispensingitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dispensing_record_id" bigint NOT NULL REFERENCES "pharmacy_dispensingrecord" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "medicine_id" bigint NOT NULL REFERENCES "pharmacy_medicine" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, "drug_name_snapshot" varchar(255) NOT NULL, "quantity_dispensed" integer unsigned NOT NULL CHECK ("quantity_dispensed" >= 0), "unit_price_snapshot" decimal NOT NULL);
CREATE TABLE "pharmacy_dispensingrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "dispensed_by_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "notes" text NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "pharmacy_medicine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "name" varchar(255) NOT NULL, "name_ta" varchar(255) NOT NULL, "brand_name" varchar(255) NOT NULL, "category" varchar(30) NOT NULL, "dosage_form" varchar(20) NOT NULL, "unit_price" decimal NOT NULL, "current_stock" integer NOT NULL, "reorder_level" integer unsigned NOT NULL CHECK ("reorder_level" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "unique_medicine_name_per_clinic" UNIQUE ("clinic_id", "name"), CONSTRAINT "medicine_stock_non_negative" CHECK ("current_stock" >= 0));
CREATE TABLE "pharmacy_stockentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "medicine_id" bigint NOT NULL REFERENCES "pharmacy_medicine" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "entry_type" varchar(20) NOT NULL, "quantity_change" integer NOT NULL, "balance_after" integer NOT NULL, "batch_number" varchar(100) NOT NULL, "expiry_date" date NULL, "notes" text NOT NULL, "actor_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL);
CREATE TABLE "prescriptions_medication" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "medicine_id" bigint NULL REFERENCES "pharmacy_medicine" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "drug_name" varchar(255) NOT NULL, "dosage" varchar(100) NOT NULL, "frequency" varchar(10) NOT NULL, "frequency_tamil" varchar(100) NOT NULL, "timing" varchar(50) NOT NULL, "timing_tamil" varchar(100) NOT NULL, "duration" varchar(100) NOT NULL, "instructions" text NOT NULL, "instructions_ta" text NOT NULL, "sort_order" smallint unsigned NOT NULL CHECK ("sort_order" >= 0), "potency" varchar(20) NOT NULL, "dilution_scale" varchar(5) NOT NULL, "pellet_count" smallint unsigned NULL CHECK ("pellet_count" >= 0));
CREATE TABLE "prescriptions_prescription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "consultation_id" bigint NOT NULL UNIQUE REFERENCES "consultations_consultation" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "diet_advice" text NOT NULL, "diet_advice_ta" text NOT NULL, "lifestyle_advice" text NOT NULL, "lifestyle_advice_ta" text NOT NULL, "exercise_advice" text NOT NULL, "exercise_advice_ta" text NOT NULL, "follow_up_date" date NULL, "follow_up_notes" text NOT NULL, "follow_up_notes_ta" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "prescriptions_procedureentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "name" varchar(255) NOT NULL, "details" text NOT NULL, "duration" varchar(100) NOT NULL, "follow_up_date" date NULL);
CREATE TABLE "prescriptions_remedyfollowupresponse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "previous_prescription_id" bigint NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "remedy_evaluated_id" bigint NULL REFERENCES "prescriptions_medication" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "response_type" varchar(30) NOT NULL, "action_taken" varchar(20) NOT NULL, "new_potency" varchar(20) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "reminders_sentreminder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "reminder_type" varchar(20) NOT NULL, "object_id" integer unsigned NOT NULL CHECK ("object_id" >= 0), "follow_up_date" date NOT NULL, "patient_email" varchar(254) NOT NULL, "sent_at" datetime NOT NULL, "resend_email_id" varchar(100) NOT NULL, CONSTRAINT "unique_reminder_per_followup" UNIQUE ("reminder_type", "object_id", "follow_up_date"));
CREATE TABLE "treatments_doctoractiontask" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "treatment_plan_id" bigint NOT NULL REFERENCES "treatments_treatmentplan" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "treatment_block_id" bigint NOT NULL REFERENCES "treatments_treatmentblock" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "assigned_doctor_id" bigint NULL REFERENCES "users_user" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED, "task_type" varchar(32) NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "due_date" date NULL, "resolved_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "treatments_sessionfeedback" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "treatment_session_id" bigint NOT NULL UNIQUE REFERENCES "treatments_treatmentsession" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "therapist_id" bigint NOT NULL REFERENCES "users_user" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "completion_status" varchar(20) NOT NULL, "response_score" smallint unsigned NOT NULL CHECK ("response_score" >= 0), "notes" text NOT NULL, "review_requested" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "treatments_treatmentblock" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "treatment_plan_id" bigint NOT NULL REFERENCES "treatments_treatmentplan" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "block_number" smallint unsigned NOT NULL CHECK ("block_number" >= 0), "start_day_number" smallint unsigned NOT NULL CHECK ("start_day_number" >= 0), "end_day_number" smallint unsigned NOT NULL CHECK ("end_day_number" >= 0), "start_date" date NOT NULL, "end_date" date NOT NULL, "status" varchar(20) NOT NULL, "replan_required" bool NOT NULL, "completed_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "uniq_tblock_plan_number" UNIQUE ("treatment_plan_id", "block_number"));
CREATE TABLE "treatments_treatmentplan" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clinic_id" bigint NOT NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "prescription_id" bigint NOT NULL REFERENCES "prescriptions_prescription" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, "total_days" smallint unsigned NOT NULL CHECK ("total_days" >= 0), "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "treatments_treatmentsession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "treatment_block_id" bigint NOT NULL REFERENCES "treatments_treatmentblock" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "day_number" smallint unsigned NOT NULL CHECK ("day_number" >= 0), "sequence_number" smallint unsigned NOT NULL CHECK ("sequence_number" >= 0), "session_date" date NOT NULL, "procedure_name" varchar(255) NOT NULL, "medium_type" varchar(20) NOT NULL, "medium_name" varchar(255) NOT NULL, "instructions" text NOT NULL, "execution_status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, CONSTRAINT "uniq_tsession_block_day_seq" UNIQUE ("treatment_block_id", "day_number", "sequence_number"));
CREATE TABLE "users_emailotp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL, "code_hash" varchar(64) NOT NULL, "attempts" smallint unsigned NOT NULL CHECK ("attempts" >= 0), "created_at" datetime NOT NULL, "expires_at" datetime NOT NULL);
