CREATE TABLE "users_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "clinic_id" bigint NULL REFERENCES "clinics_clinic" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, "role" varchar(20) NOT NULL, "is_clinic_owner" bool NOT NULL);
